// 野外公务独立有限页：只读本人亲见军令与当前本军可接触目标，不传播远方换帅结果。
#include "political_field_appointments_profile.hpp"
#include "political_field_appointments_detail.hpp"
#include "resident/views/common_presentation.hpp"
#include <algorithm>
namespace hanmo::resident { namespace {
using V=BoundaryValue;using A=V::Array;
V page_identity(const WorldIdentity& value){StableId world;const char* hex="0123456789abcdef";for(auto b:value.world_id){world.push_back(hex[b>>4]);world.push_back(hex[b&15]);}return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{value.execution_epoch}},{"revision",V{value.revision}},{"tick",V{value.tick}}});}
bool knows(const std::vector<StableId>& witnesses,const StableId& actor){return std::find(witnesses.begin(),witnesses.end(),actor)!=witnesses.end();}
}
BoundaryValue encode_political_field_appointment_quote(const PoliticalFieldAppointmentQuote& q){return boundary::obj({{"identity",page_identity(q.identity)},{"actor_id",V{q.actor_id}},{"duration",V{Integer{0}}},{"command_kind",V{q.kind}},{"command",encode_political_field_appointment_command(q.command)}});}
Outcome<BoundaryValue> query_political_field_appointments(const PoliticalFieldAppointmentContext& c,Integer cursor){
 if(!c.catalog.enabled)return {false,{},common_failure("PoliticalFieldProfileRequired").error};if(cursor<0)return {false,{},common_failure("InvalidCursor").error};const auto& actor=c.common.state().metadata.player_actor_id;if(!c.common.actor(actor))return {false,{},common_failure("PoliticalFieldObserverRequired").error};auto audit=political_field_detail::audit(c);if(!audit.ok)return {false,{},audit.error};CommonPresentation presentation(c.common.state(),c.common_catalog);A rows;Integer position=0,scanned=0,next=-1;
 auto action=[&](const StableId& text,const PoliticalFieldAppointmentCommand& command){auto q=preview_political_field_appointment(c,actor,command);return boundary::obj({{"text",V{text}},{"command",V{political_field_appointment_command_kind(command)}},{"params",encode_political_field_appointment_command(command)},{"available",V{q.ok}},{"code",V{q.ok?StableId{}:q.error.original.code}}});};
 for(auto it=c.state.authorizations.rows().rbegin();it!=c.state.authorizations.rows().rend();++it,++position){if(position<cursor)continue;if(scanned>=128||rows.size()>=16){next=position;break;}++scanned;const auto& issued=it->second;if(actor!=issued.authority.actor_id&&actor!=issued.target.next_actor_id)continue;A actions;StableId text="已在军中当面送达专项军令，尚未亲见后续答复。",source=issued.id;Integer observed=issued.tick,deadline=issued.answer_before_tick;bool final=false;const auto answer=audit.value.answers.find(issued.id);const auto withdrawal=audit.value.withdrawals.find(issued.id);
  if(answer!=audit.value.answers.end()&&knows(answer->second->witness_actor_ids,actor)){const auto& v=*answer->second;source=v.id;observed=v.tick;deadline=v.accepted?v.apply_before_tick:deadline;final=!v.accepted;text=v.accepted?"本人已接受专项军令，仍须另行办理真实交接。":"本人已婉拒；兵员、军资与原指挥来源保留。";}
  if(withdrawal!=audit.value.withdrawals.end()&&knows(withdrawal->second->witness_actor_ids,actor)){source=withdrawal->second->id;observed=withdrawal->second->tick;final=true;text="已亲见原签发人撤回此军令。";}
  if(actor==issued.target.next_actor_id&&answer!=audit.value.answers.end()&&answer->second->accepted&&c.military.application){auto applied=c.military.application(issued.id);if(!applied.ok)return {false,{},applied.error};if(applied.value){const auto& v=*applied.value;const auto* head=c.common.state().facts.find(v.id);if(!head||head->kind!="military_field_command_assigned"||head->domain!="military"||v.authorization_fact_id!=issued.id||v.acceptance_fact_id!=answer->second->id||v.actor_id!=actor||v.tick<answer->second->tick||v.tick>c.common.tick())return {false,{},common_failure("PoliticalFieldApplicationNoticeMismatch").error};source=v.id;observed=v.tick;final=true;text=issued.target.kind==MilitaryFieldCommandKind::unit?"本人已接掌具名部队。整军统帅若仍亡故，须由已任部将再获整军专项授权。":"本人已按第二份专项军令接掌军团；原编军、军资与亡者私产保留。";}}
  if(!final&&c.common.tick()>=deadline){final=true;text+="此已知军令的期限已过；未亲见结果仍待获知。";}
  if(!final&&actor==issued.target.next_actor_id){if(answer==audit.value.answers.end()){actions.push_back(action("接受野外任命",PoliticalFieldAnswerCommand{issued.id,true}));actions.push_back(action("婉拒野外任命",PoliticalFieldAnswerCommand{issued.id,false}));}else if(answer->second->accepted){auto allowed=c.military.application_preview?c.military.application_preview(actor,issued.id,answer->second->id):common_failure("MilitaryFieldAppointmentReadRequired");actions.push_back(boundary::obj({{"text",V{"办理本次指挥交接"}},{"command",V{"military_field_command_assign"}},{"params",boundary::obj({{"request_key",V{"field:"+issued.id}},{"authorization_fact_id",V{issued.id}},{"acceptance_fact_id",V{answer->second->id}}})},{"available",V{allowed.ok}},{"code",V{allowed.ok?StableId{}:allowed.error.original.code}}}));}}
  if(!final&&actor==issued.authority.actor_id){const auto* office=c.organizations.offices.find(issued.authority.office_id);if(office&&office->holder_actor_id==std::optional<StableId>{actor})actions.push_back(action("撤回野外任命",PoliticalFieldWithdrawCommand{{office->organization_id,office->id,office->epoch,actor},issued.id}));}
  auto name=presentation.display_name(issued.target.next_actor_id);if(!name.ok)return {false,{},name.error};rows.push_back(boundary::obj({{"id",V{issued.id}},{"kind",V{issued.target.kind==MilitaryFieldCommandKind::unit?"field_unit":"field_army"}},{"display_name",V{(issued.target.kind==MilitaryFieldCommandKind::unit?StableId{"部队接替 · "}:StableId{"军团接替 · "})+name.value}},{"text",V{text}},{"source_fact_id",V{source}},{"observed_tick",V{observed}},{"expires_tick",V{deadline}},{"actions",V{std::move(actions)}}}));
 }
 // 仅首屏列当前可签发目标。S2枚举被限定在本军，随后每个按钮重走原专项预览。
 if(cursor==0&&c.military.targets){auto candidates=c.military.targets(actor);if(!candidates.ok)return {false,{},candidates.error};Integer inspected=0;A actions;for(const auto& target:candidates.value){if(++inspected>64||actions.size()>=16)break;for(const auto& p:c.catalog.policies.rows()){if(p.second.organization_id!=target.organization_id)continue;for(const auto& entry:c.organizations.offices.rows()){const auto& office=entry.second;if(office.holder_actor_id!=std::optional<StableId>{actor})continue;PoliticalFieldIssueCommand command{{office.organization_id,office.id,office.epoch,actor},p.first,target};auto q=preview_political_field_appointment(c,actor,command);if(!q.ok)continue;auto name=presentation.display_name(target.next_actor_id);if(!name.ok)return {false,{},name.error};actions.push_back(action((target.kind==MilitaryFieldCommandKind::unit?StableId{"授权接部 · "}:StableId{"授权接军 · "})+name.value,command));if(actions.size()>=16)break;}if(actions.size()>=16)break;}}
  if(!actions.empty())rows.push_back(boundary::obj({{"id",V{"current_field_authority"}},{"kind",V{"field_policy"}},{"display_name",V{"军中专项任命"}},{"text",V{"仅对本军真实亡官来源与当前可接触本人签发；接部与接军分别受命、分别交接。"}},{"actions",V{std::move(actions)}}}));
 }
 return {true,boundary::obj({{"query",V{"political_field_appointments"}},{"identity",page_identity(c.common.state().identity)},{"actor_id",V{actor}},{"cursor",V{cursor}},{"next_cursor",V{next}},{"scanned",V{scanned}},{"rows",V{std::move(rows)}}}),{}};
}
}
